// What a request asks for: a value in its address (?id=…) or a text in its
// body, refused plainly when it is not there.
import { Refused } from "./refused.js";
export function asked(url, key, what) {
    const value = url.searchParams.get(key);
    if (!value)
        throw new Refused(`Say which ${what}.`);
    return value;
}
export function field(body, key) {
    const value = body?.[key];
    if (typeof value !== "string" || !value)
        throw new Refused(`Say which ${key}.`);
    return value;
}
export function optionalText(body, key) {
    const value = body?.[key];
    return typeof value === "string" ? value : undefined;
}
export function record(body, key) {
    const value = body?.[key];
    if (typeof value !== "object" || value === null)
        throw new Refused(`Say the ${key}.`);
    return value;
}
// A switch's new position from a button's body: on only when it says so.
export function on(body) {
    return body?.on === true;
}
